SELECT s.name,s.ts,s.dur,t.tid,t.name AS thread_name,t.is_main_thread FROM slice s JOIN thread_track tt ON s.track_id=tt.id JOIN thread t USING(utid) JOIN process p USING(upid) WHERE p.pid=23055 AND s.dur>0 AND (s.name GLOB 'ShadowTree::commit*' OR s.name='IntBufferBatchMountItem::mountViews' OR s.name='postAndWait' OR s.name='[ExpoImage] onResourceReady' OR (t.name='RenderThread' AND s.name GLOB 'DrawFrame*')) ORDER BY s.ts
